// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;

    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        address initial = c.rewardDistributor();
        vm.prank(caller);
        bool ok;
        try c.setRewardDistributor(caller) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.rewardDistributor() == initial);
    }
}
